                 checkit( var, imaxdiff, res, "nomask", 1.e-12 );
              end if
              delete( ncs );
           end do
           delete( ncm );
        end if
        delete( mapfile );

     end do

     if ( isvar("vars") )then
        delete( vars  )
     end if
     if ( isvar("vars2") )then
        delete( vars2 )
     end if
     delete( grid  );
